// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ResellerSite) predicate.ResellerSite {
	return predicate.ResellerSite(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ResellerSite) predicate.ResellerSite {
	return predicate.ResellerSite(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ResellerSite) predicate.ResellerSite {
	return predicate.ResellerSite(sql.NotPredicates(p))
}
